from types import SimpleNamespace

order = SimpleNamespace(id="A-17")       # dynamic, discoverable namespace
setattr(order, "routing_slip", "RS-17")  # name may come from data
vars(order)                              # {'id': 'A-17', 'routing_slip': 'RS-17'}

class Order:
    __slots__ = ("_props",)              # no accidental attributes
    def __init__(self, **props): self._props = dict(props)
    def __getattr__(self, name):
        try:
            return self._props[name]
        except KeyError:
            raise AttributeError(name) from None
    def __dir__(self): return [*super().__dir__(), *self._props]
